  "proj.tsi.tag": "Structural AI",
  "proj.tsi.short": "Our research into structural damage intelligence: reading photos of structures with engineering context and knowledge, and keeping every conclusion tied to its evidence.",
  "proj.tsi.desc": "TSI reads photos of visible damage in structures together with engineering context, inspection history and technical knowledge. It reports what it sees, what that may mean and what to do next, and never treats a photo alone as proof that a structure is safe.",
  "proj.tsi.how": "How it reasons",
  "proj.tsi.h1.t": "Reads the photo *in context*",
  "proj.tsi.h1.s": "Element, material, scale and damage history",
  "proj.tsi.h2.t": "Backed by *standards and research*",
  "proj.tsi.h2.s": "Guidance from the US, Japan, Europe and beyond",
  "proj.tsi.h3.t": "A *plain* report, not a verdict",
  "proj.tsi.h3.s": "What it sees, what it may mean, what to do",
  "proj.tsi.h4.t": "*Evidence-grounded* conclusions",
  "proj.tsi.h4.s": "Every claim traced back to its source",
  "proj.tsi.h5.t": "Measured, with *uncertainty*",
  "proj.tsi.h5.s": "Scale and confidence always shown",
  "proj.tsi.h6.t": "Unknowns stay *unknown*",
  "proj.tsi.h6.s": "Missing context is never guessed",
  "proj.tsi.reasonTitle": "A careful reading, never a verdict",
  "proj.tsi.reasonText": "TSI keeps three things apart in everything it produces, so an observation is never mistaken for an engineering conclusion.",
  "proj.tsi.r1.t": "Observation",
  "proj.tsi.r1.d": "What the evidence directly supports.",
  "proj.tsi.r1.e": "A diagonal crack is visible on the beam surface, about 1.2 mm wide, subject to scale uncertainty.",
  "proj.tsi.r2.t": "Interpretation",
  "proj.tsi.r2.d": "What the pattern may fit, given the context.",
  "proj.tsi.r2.e": "Its direction may fit a shear-related pattern, but a photo alone can't confirm the cause.",
  "proj.tsi.r3.t": "Recommendation",
  "proj.tsi.r3.d": "What to consider doing next.",
  "proj.tsi.r3.e": "Have a qualified structural engineer inspect the beam, especially if the crack is new or growing.",
