  "demo.v.crack-beam-rc.seen": "A diagonal crack-like line runs up from the support towards mid-span, with one short branch.",
  "demo.v.spall-column-rc.seen": "Concrete has broken away from the column face, exposing two corroded reinforcing bars and a link, with rust streaks below; a diagonal crack runs through the damaged area.",
  "demo.v.damp-wall-masonry.seen": "The lower part of a brick wall is darker and looks damp, with white salt deposits along a wavy line.",
  "demo.i.crack-beam-rc.int": "Its direction near the support may fit a shear-related pattern. The photo alone can't confirm the cause.",
  "demo.i.crack-beam-rc.short": "May fit shear",
  "demo.i.crack-beam-rc.causes": "Shear load near the support, overloading, or less reinforcement than needed.",
  "demo.i.crack-beam-masonry.int": "A brick lintel that has dropped in the middle, with a stepped crack climbing from its end, usually fits a lintel that is sagging or losing its support, for example a corroded or missing steel lintel behind the bricks.",
  "demo.i.crack-beam-masonry.short": "Lintel sagging?",
  "demo.i.crack-beam-masonry.causes": "A corroded, missing or undersized steel lintel behind the bricks, too little bearing at its ends, or movement of the wall at its supports.",
  "demo.i.fine-rc.short": "Shrinkage or reaction?",
  "demo.i.fine-rc.causes": "Crazing from early drying of the concrete surface or, less often, alkali–silica reaction inside the concrete.",
  "demo.i.fine-masonry.int": "Fine map-like cracking in a render or plaster finish usually fits surface shrinkage rather than structural movement.",
  "demo.i.fine-masonry.short": "Surface shrinkage?",
  "demo.i.fine-masonry.causes": "Drying shrinkage of the render or plaster, or temperature changes at the surface.",
  "demo.i.spall-rc.int": "This fits corrosion of the reinforcement pushing the concrete cover off. How much steel has been lost can't be judged from the photo.",
  "demo.i.spall-rc.short": "Corrosion-related?",
  "demo.i.spall-rc.causes": "Water and chlorides, or carbonation, reaching the steel through thin or cracked cover.",
  "demo.i.damp-masonry.int": "A tide line with salts fits moisture moving up or through the masonry and drying out at the surface.",
  "demo.i.damp-masonry.short": "Rising moisture?",
  "demo.i.damp-masonry.causes": "Rising damp, a damaged damp-proof course, leaking pipes or gutters, or ground outside higher than the floor.",
  "demo.dm.crack.dont": "Don't fill or paint over the crack before it has been inspected.",
  "demo.dm.crack.change": "A crack that is new or growing raises the grade; an old crack that hasn't changed in years lowers the concern.",
  "demo.dm.fine.do": "Record the area with a scale reference, so later photos can show whether it changes.",
  "demo.dm.fine.change": "Wider, straight or stepped cracks, or cracks that grow, would raise the grade.",
  "demo.dm.spall-rc.dont": "Don't patch it with mortar or paint the steel before the cause and the steel loss are assessed.",
  "demo.dm.damp-masonry.check": "Leaks, gutters and the ground level outside, and whether bricks or mortar are crumbling.",
