  "proj.context-guardian.tagline": "Garde les agents de code dans la carte de votre app",
  "proj.context-guardian.desc": "Avant qu’un agent de code ne modifie quoi que ce soit, Context Guardian lui indique les fonctionnalités, règles et vérifications concernées. À la fin, il compare la modification à cette carte et signale ce que l’agent a oublié.",
