  "proj.context-guardian.h3.s": "Un changement iOS oublié sur Android, ou une règle affaiblie",
  "proj.context-guardian.h4.t": "Fonctionne avec *vos agents*",
  "proj.context-guardian.h4.s": "Claude Code, Codex, Gemini CLI, Cursor, Copilot",
  "proj.context-guardian.h5.t": "Local et *privé*",
  "proj.context-guardian.h5.s": "Aucun appel de modèle, aucun réseau, aucune télémétrie",
  "proj.context-guardian.h6.t": "Les agents n’exécutent que des commandes *sûres*",
  "proj.context-guardian.h6.s": "Le reste attend votre accord ; jamais de publication ni de push",
  "proj.safe-eject.h1.t": "Trouve *chaque processus* sur le disque",
  "proj.safe-eject.h1.s": "Agents IA, terminaux, serveurs de dev et plus",
