  "proj.safe-eject.h2.s": "Une raison claire et une solution pour chacun",
  "proj.safe-eject.h3.t": "Montre *d’où il vient*",
  "proj.safe-eject.h3.s": "Quelle app et quelle fenêtre l’ont lancé",
  "proj.safe-eject.h4.t": "Quitter et éjecter *d’un coup*",
  "proj.safe-eject.h4.s": "Forcer à quitter seulement ceux qui refusent",
  "proj.safe-eject.h5.t": "Désactive *Spotlight* pour un disque",
  "proj.safe-eject.h5.s": "Une raison fréquente de disque occupé",
  "proj.safe-eject.h6.t": "*Aucune dépendance*",
  "proj.safe-eject.h6.s": "Un seul fichier Python, bibliothèque standard",
  "proj.polyshot.h1.t": "*Toutes les langues*, un seul design",
