  "proj.polyshot.h3.t": "Des mises en page *qui se démarquent*",
  "proj.polyshot.h3.s": "Appareils 3D, duos, inclinés et pleine page",
  "proj.polyshot.h4.t": "Votre *marque*, votre style",
  "proj.polyshot.h4.s": "Dégradés, cadres, polices et couleurs",
  "proj.polyshot.h5.t": "Des *tailles* exactes",
  "proj.polyshot.h5.s": "Au pixel près pour l’App Store et Google Play",
