  "filter.all": "Tout",
  "hero.ctaWork": "Voir le portfolio",
  "hero.github": "Open source sur GitHub",
  "chip.inDev": "En développement",
  "proj.tsi.tag": "IA structurelle",
  "proj.tsi.short": "Notre recherche en intelligence des dommages structurels : lire les photos d’ouvrages avec le contexte et les connaissances d’ingénierie, en rattachant chaque conclusion à ses preuves.",
  "proj.tsi.desc": "TSI lit les photos de dommages visibles sur les ouvrages en tenant compte du contexte d’ingénierie, de l’historique des inspections et des connaissances techniques. Il indique ce qu’il voit, ce que cela peut signifier et ce qu’il faut faire ensuite, sans jamais considérer une photo seule comme la preuve qu’un ouvrage est sûr.",
  "proj.tsi.how": "Sa façon de raisonner",
  "proj.tsi.h1.t": "Lit la photo *dans son contexte*",
  "proj.tsi.h1.s": "Élément, matériau, échelle et historique des dommages",
  "proj.tsi.h2.t": "Fondé sur les *normes et la recherche*",
  "proj.tsi.h2.s": "Références des États-Unis, du Japon, d’Europe et d’ailleurs",
  "proj.tsi.h3.t": "Un rapport *clair*, pas un verdict",
  "proj.tsi.h3.s": "Ce qu’il voit, ce que cela peut signifier, que faire",
  "proj.tsi.h4.t": "Des conclusions *fondées sur les preuves*",
  "proj.tsi.h4.s": "Chaque affirmation reliée à sa source",
  "proj.tsi.h5.t": "Mesuré, avec son *incertitude*",
  "proj.tsi.h5.s": "Échelle et niveau de confiance toujours affichés",
  "proj.tsi.h6.t": "L’inconnu reste *inconnu*",
  "proj.tsi.h6.s": "Le contexte manquant n’est jamais deviné",
  "proj.tsi.reasonTitle": "Une lecture attentive, jamais un verdict",
  "proj.tsi.reasonText": "TSI sépare toujours trois choses, pour qu’une observation ne soit jamais confondue avec une conclusion d’ingénierie.",
  "proj.tsi.r1.t": "Observation",
  "proj.tsi.r1.d": "Ce que les preuves établissent directement.",
  "proj.tsi.r1.e": "Une fissure diagonale est visible à la surface de la poutre, d’environ 1,2 mm de large, sous réserve de l’incertitude d’échelle.",
  "proj.tsi.r2.t": "Interprétation",
  "proj.tsi.r2.d": "Ce à quoi le motif peut correspondre, compte tenu du contexte.",
  "proj.tsi.r2.e": "Son orientation peut évoquer un effort tranchant, mais une photo seule ne permet pas d’en confirmer la cause.",
  "proj.tsi.r3.t": "Recommandation",
  "proj.tsi.r3.d": "Ce qu’il convient d’envisager ensuite.",
  "proj.tsi.r3.e": "Faire inspecter la poutre par un ingénieur structure qualifié, surtout si la fissure est récente ou s’agrandit.",
  "proj.tsi.status": "Recherche et développement",
  "proj.tsi.focusLabel": "Domaine",
  "proj.tsi.focus": "Dommages visibles sur les ouvrages et constructions",
  "proj.tsi.contact": "Vous travaillez sur des inspections, des données structurelles ou de la recherche ? Nous serions ravis d’échanger avec vous.",
  "range.eyebrow": "Notre univers",
  "range.title": "Des puzzles douillets à l’intelligence structurelle.",
  "range.text": "Le même soin dans tout ce que nous créons : des jeux et des apps du quotidien aujourd’hui, et une recherche qui aide à lire les ouvrages qui nous entourent.",
  "range.cta": "Découvrir TSI",
