  "demo.text": "Modifiez ce que l’on sait de la photo et observez ce que TSI accepte d’affirmer. Moins de contexte, c’est moins de conclusions, jamais plus de suppositions.",
  "demo.note": "Illustration sur un exemple fixe, pas un résultat de modèle. TSI est en recherche et développement.",
  "demo.layers": "Calques",
