  "demo.text2": "Choisissez un exemple, modifiez ce que l’on sait de la photo et observez comment le rapport change. Moins de contexte, c’est moins de conclusions, jamais plus de suppositions.",
  "demo.note2": "Exemples illustrés, pas un résultat de modèle. TSI est en recherche et développement.",
  "demo.noScale": "Dimensions impossibles à mesurer : la photo n’a aucune référence d’échelle.",
