  "proj.tsi.tag": "Strukturelle KI",
  "proj.tsi.short": "Unsere Forschung zu Schadensintelligenz für Bauwerke: Fotos von Bauwerken mit Ingenieurkontext und Fachwissen auswerten und jede Schlussfolgerung an ihre Belege binden.",
  "proj.tsi.desc": "TSI wertet Fotos sichtbarer Schäden an Bauwerken zusammen mit Ingenieurkontext, Prüfhistorie und technischem Wissen aus. Es zeigt, was zu sehen ist, was das bedeuten kann und was als Nächstes zu tun ist – und betrachtet ein Foto allein nie als Beweis, dass ein Bauwerk sicher ist.",
  "proj.tsi.how": "So denkt TSI",
  "proj.tsi.h1.t": "Liest das Foto *im Kontext*",
  "proj.tsi.h1.s": "Bauteil, Werkstoff, Maßstab und Schadensverlauf",
  "proj.tsi.h2.t": "Gestützt auf *Normen und Forschung*",
  "proj.tsi.h2.s": "Leitfäden aus den USA, Japan, Europa und darüber hinaus",
  "proj.tsi.h3.t": "Ein *verständlicher* Bericht, kein Urteil",
  "proj.tsi.h3.s": "Was es sieht, was es bedeuten kann, was zu tun ist",
  "proj.tsi.h4.t": "*Belegte* Schlussfolgerungen",
  "proj.tsi.h4.s": "Jede Aussage bis zur Quelle nachvollziehbar",
  "proj.tsi.h5.t": "Gemessen, mit *Unsicherheit*",
  "proj.tsi.h5.s": "Maßstab und Konfidenz immer sichtbar",
  "proj.tsi.h6.t": "Unbekanntes bleibt *unbekannt*",
  "proj.tsi.h6.s": "Fehlender Kontext wird nie erraten",
  "proj.tsi.reasonTitle": "Eine sorgfältige Einschätzung, nie ein Urteil",
  "proj.tsi.reasonText": "TSI trennt in allem, was es liefert, drei Dinge – damit eine Beobachtung nie mit einer ingenieurtechnischen Schlussfolgerung verwechselt wird.",
  "proj.tsi.r1.t": "Beobachtung",
  "proj.tsi.r1.d": "Was die Belege direkt stützen.",
  "proj.tsi.r1.e": "Auf der Balkenoberfläche ist ein diagonaler Riss sichtbar, etwa 1,2 mm breit, vorbehaltlich der Maßstabsunsicherheit.",
  "proj.tsi.r2.t": "Interpretation",
  "proj.tsi.r2.d": "Wozu das Muster im Kontext passen könnte.",
  "proj.tsi.r2.e": "Die Richtung könnte auf Schub hindeuten, doch ein Foto allein kann die Ursache nicht bestätigen.",
  "proj.tsi.r3.t": "Empfehlung",
  "proj.tsi.r3.d": "Was als Nächstes zu erwägen ist.",
  "proj.tsi.r3.e": "Den Balken von einer qualifizierten Tragwerksplanerin oder einem Tragwerksplaner prüfen lassen, besonders wenn der Riss neu ist oder wächst.",
  "proj.tsi.status": "Forschung und Entwicklung",
  "proj.tsi.focusLabel": "Schwerpunkt",
  "proj.tsi.focus": "Sichtbare Schäden an Bauwerken und Bauten",
  "proj.tsi.contact": "Sie arbeiten an Bauwerksprüfungen, Tragwerksdaten oder Forschung? Wir freuen uns auf Ihre Nachricht.",
  "range.eyebrow": "Unser Spektrum",
  "range.title": "Von gemütlichen Puzzles bis zu struktureller Intelligenz.",
  "range.text": "Dieselbe Sorgfalt steckt in allem, was wir bauen: heute Spiele und Alltags-Apps, dazu Forschung, die hilft, die Bauwerke um uns herum zu verstehen.",
  "range.cta": "TSI entdecken",
