  "demo.text2": "Wählen Sie ein Beispiel, ändern Sie, was über das Foto bekannt ist, und sehen Sie, wie sich der Bericht ändert. Weniger Kontext heißt weniger Schlussfolgerungen, nicht mehr Vermutungen.",
  "demo.note2": "Illustrierte Beispiele, keine Modellausgabe. TSI befindet sich in Forschung und Entwicklung.",
