  "proj.context-guardian.tagline": "Tiene gli agenti di codice dentro la mappa della tua app",
  "proj.context-guardian.desc": "Prima che un agente di codice modifichi qualcosa, Context Guardian gli dice quali funzionalità, regole e controlli tocca il compito. Alla fine confronta la modifica con la mappa e segnala ciò che l’agente ha trascurato.",
