  "chip.inDev": "In sviluppo",
  "proj.tsi.tag": "IA strutturale",
  "proj.tsi.short": "La nostra ricerca sull’intelligenza dei danni strutturali: leggere le foto delle strutture con contesto e conoscenze ingegneristiche, legando ogni conclusione alle sue prove.",
  "proj.tsi.desc": "TSI legge le foto dei danni visibili nelle strutture insieme al contesto ingegneristico, alla storia delle ispezioni e alle conoscenze tecniche. Indica cosa vede, cosa può significare e cosa fare dopo, e non considera mai una sola foto come prova che una struttura sia sicura.",
  "proj.tsi.how": "Come ragiona",
  "proj.tsi.h1.t": "Legge la foto *nel suo contesto*",
  "proj.tsi.h1.s": "Elemento, materiale, scala e storia del danno",
  "proj.tsi.h2.t": "Basato su *norme e ricerca*",
  "proj.tsi.h2.s": "Linee guida da USA, Giappone, Europa e oltre",
  "proj.tsi.h3.t": "Un report *chiaro*, non un verdetto",
  "proj.tsi.h3.s": "Cosa vede, cosa può significare, cosa fare",
  "proj.tsi.h4.t": "Conclusioni *basate sulle prove*",
  "proj.tsi.h4.s": "Ogni affermazione ricondotta alla sua fonte",
  "proj.tsi.h5.t": "Misurato, con la sua *incertezza*",
  "proj.tsi.h5.s": "Scala e affidabilità sempre in vista",
  "proj.tsi.h6.t": "L’ignoto resta *ignoto*",
  "proj.tsi.h6.s": "Il contesto mancante non viene mai indovinato",
  "proj.tsi.reasonTitle": "Una lettura attenta, mai un verdetto",
  "proj.tsi.reasonText": "TSI tiene sempre separate tre cose, così un’osservazione non viene mai scambiata per una conclusione ingegneristica.",
  "proj.tsi.r1.t": "Osservazione",
  "proj.tsi.r1.d": "Ciò che le prove supportano direttamente.",
  "proj.tsi.r1.e": "Sulla superficie della trave è visibile una fessura diagonale larga circa 1,2 mm, salvo incertezza di scala.",
  "proj.tsi.r2.t": "Interpretazione",
  "proj.tsi.r2.d": "A cosa può corrispondere lo schema, dato il contesto.",
  "proj.tsi.r2.e": "L’andamento può far pensare al taglio, ma una sola foto non può confermarne la causa.",
  "proj.tsi.r3.t": "Raccomandazione",
  "proj.tsi.r3.d": "Cosa valutare come passo successivo.",
  "proj.tsi.r3.e": "Far ispezionare la trave da un ingegnere strutturista qualificato, soprattutto se la fessura è recente o in crescita.",
  "proj.tsi.status": "Ricerca e sviluppo",
  "proj.tsi.focusLabel": "Ambito",
  "proj.tsi.focus": "Danni visibili in strutture e costruzioni",
  "proj.tsi.contact": "Lavori su ispezioni, dati strutturali o ricerca? Ci farebbe piacere sentirti.",
  "range.eyebrow": "Il nostro raggio d’azione",
  "range.title": "Dai puzzle rilassanti all’intelligenza strutturale.",
  "range.text": "La stessa cura in tutto ciò che facciamo: giochi e app di tutti i giorni oggi, e una ricerca che aiuta a leggere le strutture che ci circondano.",
  "range.cta": "Scopri TSI",
