  "cov.f5d": "Terreno, pendii e acqua intorno alle strutture",
  "cov.f6": "Rivestimenti, intonaci, giunti e appoggi",
  "cov.f6d": "Sistemi protettivi e funzionali",
  "cov.regions": "Le conoscenze provengono da linee guida e ricerche di Stati Uniti, Giappone, Unione europea, Canada, Regno Unito, Nuova Zelanda e Turchia, oltre che da fonti internazionali.",
  "stat.units2": "unità di conoscenza da 148 fonti",
