  "stat.note2": "Dalla ricerca della Fase 1 di Tecto, novembre 2026. Misurata su set di test tenuti da parte; non è una garanzia per ogni foto.",
  "demo.i.damp-any.int": "Una linea di risalita con depositi bianchi è compatibile con umidità che entra nell’elemento ed evapora in superficie.",
  "demo.i.damp-any.short": "Umidità?",
  "demo.i.damp-any.causes": "Acqua dal terreno, un tubo o una grondaia che perde, o terreno esterno più alto del pavimento.",
  "demo.dm.damp-any.check": "Perdite, grondaie e quota del terreno esterno, ed eventuali sgretolamenti, macchie di ruggine o fessure in superficie.",
  "demo.dm.damp-any.change": "Umidità che continua ad allargarsi, o sgretolamenti, macchie di ruggine o fessure che compaiono in superficie, alzerebbero il livello.",
