  "chip.inDev": "開発中",
  "proj.tsi.tag": "構造AI",
  "proj.tsi.short": "構造物の損傷インテリジェンスに関する研究です。構造物の写真を工学的な文脈や知識とあわせて読み解き、すべての結論を根拠に結びつけます。",
  "proj.tsi.desc": "TSIは、構造物に見える損傷の写真を、工学的な文脈、点検履歴、技術的な知識とあわせて読み解きます。見えていること、それが意味しうること、次にすべきことを示し、写真だけで構造物が安全だと判断することはありません。",
  "proj.tsi.how": "推論のしかた",
  "proj.tsi.h1.t": "写真を*文脈*と あわせて読む",
  "proj.tsi.h1.s": "部材、材料、スケール、損傷の経緯",
  "proj.tsi.h2.t": "*規格と研究*に 裏付けられた知識",
  "proj.tsi.h2.s": "米国、日本、欧州などの指針",
  "proj.tsi.h3.t": "判定ではなく、*わかりやすい*報告",
  "proj.tsi.h3.s": "見えること、考えられる意味、次にすること",
  "proj.tsi.h4.t": "*根拠に基づく*結論",
  "proj.tsi.h4.s": "すべての主張を出典までたどれる",
  "proj.tsi.h5.t": "*不確かさ*も含めて計測",
  "proj.tsi.h5.s": "スケールと確信度を常に表示",
  "proj.tsi.h6.t": "不明なことは*不明*のまま",
  "proj.tsi.h6.s": "足りない情報を推測で補わない",
  "proj.tsi.reasonTitle": "慎重に読み解き、断定はしない",
  "proj.tsi.reasonText": "TSIは出力のすべてで3つを区別します。観察が工学的な結論と取り違えられることはありません。",
  "proj.tsi.r1.t": "観察",
  "proj.tsi.r1.d": "根拠が直接示していること。",
  "proj.tsi.r1.e": "梁の表面に斜めのひび割れが見られます。幅は約1.2 mmで、スケールの不確かさがあります。",
  "proj.tsi.r2.t": "解釈",
  "proj.tsi.r2.d": "文脈から見て、そのパターンが当てはまりうること。",
  "proj.tsi.r2.e": "向きはせん断によるパターンと整合する可能性がありますが、写真だけでは原因を確定できません。",
  "proj.tsi.r3.t": "推奨",
  "proj.tsi.r3.d": "次に検討すべきこと。",
  "proj.tsi.r3.e": "特にひび割れが新しい、または広がっている場合は、資格のある構造技術者に梁を点検してもらってください。",
  "proj.tsi.status": "研究開発中",
  "proj.tsi.focusLabel": "対象",
  "proj.tsi.focus": "構造物や建設物に見える損傷",
  "proj.tsi.contact": "点検、構造データ、研究に取り組んでいる方からのご連絡をお待ちしています。",
  "range.eyebrow": "私たちの領域",
