  "chip.inDev": "개발 중",
  "proj.tsi.tag": "구조 AI",
  "proj.tsi.short": "구조물 손상 인텔리전스에 관한 연구입니다. 구조물 사진을 공학적 맥락과 지식과 함께 읽고, 모든 결론을 근거에 연결합니다.",
  "proj.tsi.desc": "TSI는 구조물에 보이는 손상 사진을 공학적 맥락, 점검 이력, 기술 지식과 함께 읽습니다. 무엇이 보이는지, 그것이 무엇을 의미할 수 있는지, 다음에 무엇을 해야 하는지 알려 주며, 사진 한 장만으로 구조물이 안전하다고 판단하지 않습니다.",
  "proj.tsi.how": "추론 방식",
  "proj.tsi.h1.t": "사진을 *맥락*과 함께 읽음",
  "proj.tsi.h1.s": "부재, 재료, 축척, 손상 이력",
  "proj.tsi.h2.t": "*기준과 연구*에 근거",
  "proj.tsi.h2.s": "미국, 일본, 유럽 등의 지침",
  "proj.tsi.h3.t": "판정이 아닌 *쉬운* 보고서",
  "proj.tsi.h3.s": "보이는 것, 의미할 수 있는 것, 해야 할 일",
  "proj.tsi.h4.t": "*근거에 기반한* 결론",
  "proj.tsi.h4.s": "모든 주장을 출처까지 추적",
  "proj.tsi.h5.t": "*불확실성*까지 함께 측정",
  "proj.tsi.h5.s": "축척과 신뢰도를 항상 표시",
  "proj.tsi.h6.t": "모르는 것은 *모르는 것*으로",
  "proj.tsi.h6.s": "빠진 맥락을 추측으로 채우지 않음",
  "proj.tsi.reasonTitle": "신중한 해석, 결코 단정이 아닌",
  "proj.tsi.reasonText": "TSI는 모든 결과에서 세 가지를 구분합니다. 관찰이 공학적 결론으로 오해되지 않도록 하기 위해서입니다.",
  "proj.tsi.r1.t": "관찰",
