  "demo.q.history": "손상이 새로 생겼나요, 아니면 최근에 커졌나요?",
  "demo.v.crack-beam-rc.seen": "지점에서 경간 중앙 쪽으로 대각선 균열 형태의 선이 올라가며, 짧은 가지가 하나 있습니다.",
  "demo.v.spall-column-rc.seen": "기둥 면에서 콘크리트가 떨어져 나가 부식된 주철근 두 개와 띠철근 하나가 드러났고, 그 아래로 녹물 자국이 있습니다. 손상 부위를 대각선 균열이 가로지릅니다.",
  "demo.v.damp-wall-masonry.seen": "벽돌 벽 아래쪽이 더 어둡고 젖어 보이며, 물결 모양 선을 따라 흰 염분(백화)이 있습니다.",
  "demo.i.crack-beam-rc.int": "지점 근처의 방향은 전단과 관련된 패턴에 해당할 수 있습니다. 사진만으로는 원인을 확정할 수 없습니다.",
  "demo.i.crack-beam-rc.short": "전단 가능성",
  "demo.i.crack-beam-rc.causes": "지점 근처의 전단력, 과하중, 또는 필요한 양보다 적은 철근.",
  "demo.i.crack-beam-masonry.int": "가운데가 내려앉은 벽돌 인방과 그 끝에서 위로 올라가는 계단 모양 균열은 대개 인방이 처지고 있거나 지지를 잃고 있는 경우에 해당합니다. 예를 들어 벽돌 뒤의 강재 인방이 부식되었거나 아예 없는 경우입니다.",
  "demo.i.crack-beam-masonry.short": "인방 처짐?",
  "demo.i.crack-beam-masonry.causes": "벽돌 뒤 강재 인방의 부식, 누락 또는 단면 부족, 양 끝의 걸침 길이 부족, 또는 지지부에서의 벽체 움직임.",
  "demo.i.fine-rc.short": "수축 또는 반응?",
  "demo.i.fine-rc.causes": "콘크리트 표면의 초기 건조로 생긴 거북등 모양 잔균열(크레이징), 드물게 콘크리트 내부의 알칼리-실리카 반응.",
  "demo.i.fine-masonry.int": "미장이나 플라스터 마감의 지도 모양 미세 균열은 대개 구조적 움직임보다는 표면 수축에 해당합니다.",
  "demo.i.fine-masonry.short": "표면 수축?",
  "demo.i.fine-masonry.causes": "미장재나 플라스터의 건조 수축, 또는 표면의 온도 변화.",
  "demo.i.spall-rc.int": "철근 부식으로 피복 콘크리트가 밀려 떨어진 경우에 해당합니다. 철근이 얼마나 손실되었는지는 사진으로 판단할 수 없습니다.",
  "demo.i.spall-rc.short": "부식 관련?",
  "demo.i.spall-rc.causes": "얇거나 균열이 있는 피복을 통해 물과 염화물, 또는 중성화가 철근까지 도달한 것.",
  "demo.i.damp-masonry.int": "염분이 남은 수위선 모양의 자국은 습기가 조적을 따라 올라오거나 통과해 표면에서 마르는 경우에 해당합니다.",
  "demo.i.damp-masonry.short": "상승 습기?",
  "demo.i.damp-masonry.causes": "지면에서 올라오는 습기, 손상된 방습층, 배관이나 홈통 누수, 또는 바닥보다 높은 외부 지면.",
