  "demo.dm.fine.do": "나중에 찍은 사진으로 변화 여부를 확인할 수 있도록 축척 기준과 함께 해당 부위를 기록하세요.",
  "demo.dm.fine.change": "더 넓거나 곧거나 계단 모양인 균열, 또는 커지는 균열은 등급을 높입니다.",
