  "demo.v.damp-column-rc.seen": "콘크리트 기둥 밑동이 더 어둡고 젖어 보이며, 물결 모양 선을 따라 흰 석출물이 있고 한쪽 모서리에 작은 녹 얼룩이 있습니다.",
  "demo.v.damp-column-masonry.seen": "벽돌 기둥 밑동이 더 어둡고 젖어 보이며, 물결 모양 선을 따라 흰 염분(백화)이 있습니다.",
  "demo.v.damp-wall-rc.seen": "콘크리트 벽 아래쪽이 더 어둡고 젖어 보이며, 물결 모양 선을 따라 흰 석출물과 희미한 녹 얼룩이 있습니다.",
  "demo.i.crack-column-rc.int": "기둥을 가로지르는 대각선 균열은 전단과 관련된 패턴에 해당할 수 있으며, 이는 보보다 기둥에서 더 중요합니다. 사진만으로는 원인을 확정할 수 없습니다.",
  "demo.i.crack-column-rc.short": "전단 가능성",
  "demo.i.crack-column-rc.causes": "지진 같은 수평 하중에 의한 전단, 띠철근 부족이나 너무 넓은 간격, 또는 과하중.",
  "demo.i.crack-column-masonry.int": "기둥의 벽돌을 갈라 놓는 거의 수직인 균열은 위에서 누르는 하중이 너무 클 때 생기는 경우가 많습니다. 사진만으로는 원인을 확정할 수 없습니다.",
  "demo.i.crack-column-masonry.short": "과하중?",
  "demo.i.crack-column-masonry.causes": "기둥이 견디도록 지어진 것보다 큰 하중, 약한 벽돌이나 모르타르, 또는 가장자리에 너무 가깝게 걸리는 하중.",
  "demo.i.crack-wall-rc.int": "창 모서리에서 뻗어 나온 가는 균열은 수축이나 움직임으로 모서리에 응력이 집중되어 생기는 경우가 많습니다. 벽에서는 대개 보나 기둥보다 우려가 덜합니다.",
  "demo.i.crack-wall-rc.short": "모서리 응력?",
  "demo.i.crack-wall-rc.causes": "개구부 주변에서 구속된 콘크리트의 수축, 온도에 따른 움직임, 또는 모서리 보강근 부족.",
  "demo.i.crack-wall-masonry.int": "창 모서리에서 줄눈을 따라 이어지는 계단 모양 균열은 아래 기초의 부등침하에 해당하는 경우가 많습니다.",
  "demo.i.crack-wall-masonry.short": "침하?",
  "demo.i.crack-wall-masonry.causes": "기초의 부등침하나 움직임. 예를 들어 점토 지반의 수축, 배수관 누수, 가까운 나무뿌리 등.",
  "demo.i.fine-rc.int": "콘크리트 표면에서는 지도 모양의 미세 균열이 대개 표면의 초기 수축에 해당합니다. 드물게 시험이 필요한 콘크리트 내부 반응일 수 있습니다.",
  "demo.i.spall-masonry.int": "이처럼 벽돌 표면이 벗겨지는 것은 대개 젖은 조적의 동해나 염분 손상에 해당하며, 그 자체로 구조적 문제는 아닙니다.",
  "demo.i.spall-masonry.short": "동해 또는 염분?",
  "demo.i.spall-masonry.causes": "벽돌 속 물의 동결, 벽이 마르면서 생기는 염분 결정화, 또는 습기를 가두는 단단한 시멘트 모르타르나 투습이 안 되는 도막.",
  "demo.i.damp-rc.int": "흰 석출물이 있는 수위선 모양 자국은 물이 콘크리트로 스며들었다가 표면에서 마르는 경우에 해당합니다. 녹 얼룩은 표면 가까이 있는 철근이 부식되기 시작했다는 뜻일 수도 있고 금속 고정 철물에서 나온 것일 수도 있으므로, 현장에서 확인해야 합니다.",
  "demo.i.damp-rc.short": "물 침투?",
  "demo.i.damp-rc.causes": "지면에서 올라오는 물, 배관이나 홈통 누수, 또는 바닥보다 높은 외부 지면.",
  "demo.dm.crack.do": "균열 양 끝에 표시하고 날짜를 적은 뒤, 커지면 알 수 있도록 축척 기준을 함께 두고 사진을 찍으세요. 어떤 균열인지는 구조 엔지니어에게 확인을 받으세요.",
  "demo.dm.crack-rc.check": "주변의 다른 균열, 처짐·기울어짐·배부름, 반대쪽 면의 같은 균열.",
  "demo.dm.crack-masonry.check": "안쪽 면의 균열, 배부름·기울어짐·처짐, 위에서 해당 부재에 얹혀 있는 것, 주변 문이나 창문이 뻑뻑한지, 기초 근처 배수관 누수.",
  "demo.dm.fine.dont": "균열이 넓어지거나 선을 따라 이어지기 시작하면 뒤쪽 부재가 건전하다고 단정하지 마세요.",
  "demo.dm.fine.check": "더 넓거나 곧거나 계단 모양인 균열이 있는지, 두드렸을 때 표면에서 들뜬 소리가 나는지.",
  "demo.dm.spall-rc.do": "자격을 갖춘 구조 엔지니어에게 빨리 점검을 받으세요. 조각이 떨어질 수 있으니 주변에 사람이 가까이 가지 않도록 하세요.",
  "demo.dm.spall-rc.check": "주변의 다른 박락이나 녹 얼룩, 철근을 따라 생긴 균열.",
  "demo.dm.spall-rc.change": "단면이 크게 줄어든 철근이나 여러 곳의 비슷한 손상은 우려를 더 높입니다.",
  "demo.dm.spall-masonry.do": "젖는 원인을 찾아 막은 다음, 손상된 벽돌을 평가받고 필요한 곳은 교체하세요.",
  "demo.dm.spall-masonry.dont": "단단한 시멘트 모르타르로 줄눈을 다시 채우거나 벽돌을 코팅으로 막지 마세요. 습기가 갇혀 손상이 더 심해질 수 있습니다.",
  "demo.dm.spall-masonry.check": "홈통이나 배관 누수, 빗물 튐이나 지면에서 올라오는 습기, 손상이 퍼지고 있는지, 벽돌이 얼마나 깊이 떨어져 나갔는지.",
  "demo.dm.spall-masonry.change": "벽돌 조적을 약화시킬 만큼 깊은 손실이나 많은 벽돌로 퍼지는 손상은 등급을 높입니다.",
  "demo.dm.damp.do": "먼저 물의 원인을 찾아 고치고, 보수하기 전에 충분히 말리세요.",
  "demo.dm.damp.dont": "투습이 안 되는 페인트나 미장재로 막지 마세요. 습기가 갇힐 수 있습니다.",
  "demo.dm.damp-rc.check": "누수, 홈통, 외부 지면 높이, 그리고 녹 얼룩이나 철근을 따라 생긴 균열.",
  "demo.dm.damp-rc.change": "녹 얼룩이 퍼지거나, 철근을 따라 균열이 생기거나, 콘크리트가 떨어져 나가면 철근이 부식되고 있다는 뜻이므로 등급을 높입니다.",
  "demo.call.recSoon": "엔지니어 조기 점검",
  "demo.call.active": "진행 중일 가능성",
  "demo.call.dormant": "안정적일 가능성",
  "demo.h.growing": "새로 생겼거나 커지고 있어 손상이 아직 진행 중일 가능성이 큽니다.",
  "demo.h.stable": "수년간 변화가 없어 빠르게 악화되고 있을 가능성은 낮습니다. 그래도 점검으로 이를 확인해야 합니다.",
  "demo.h.growingDo": "기다리지 말고 빨리 점검을 받으세요. 그때까지 축척 기준을 함께 두고 매주 사진을 찍으세요.",
  "demo.h.stableDo": "변화가 없는지 확인하도록 1년에 한두 번 축척 기준을 함께 두고 계속 사진을 찍으세요.",
  "who.eyebrow": "대상",
  "who.title": "건물을 돌보는 사람들을 위해",
  "who.note": "TSI는 연구 개발 중이며, 다음은 TSI가 염두에 두고 있는 사람들입니다.",
  "who.c1.t": "주택 소유자와 거주자",
  "who.c1.d": "균열이나 습기 얼룩을 촬영하면 그것이 무엇을 의미할 수 있는지, 언제 엔지니어를 불러야 하는지 차분하고 쉬운 설명을 받을 수 있습니다.",
  "who.c2.t": "건물 및 현장 관리자",
  "who.c2.d": "여러 건물의 손상을 날짜별로 비교할 수 있게 기록하고, 무엇부터 살펴야 하는지 파악할 수 있습니다.",
  "who.c3.t": "엔지니어와 점검자",
  "who.c3.d": "출처가 달린 구조화된 관찰에서 시작하므로, 현장 방문과 보고서 작성을 한발 앞서 시작할 수 있습니다.",
  "cov.eyebrow": "범위",
  "cov.title": "TSI가 다루는 범위",
  "cov.text": "TSI는 여섯 가지 재료군을 대상으로 만들어지고 있습니다. 검증은 콘크리트부터 한 재료군씩 진행하며, 사진 입력, 등급 판정, 권고, 보고서는 이미 여섯 가지 모두에 맞게 구축되어 있습니다.",
  "cov.now": "진행 중",
  "cov.next": "다음",
  "cov.later": "예정",
  "cov.stage": "{n}단계 / 6",
  "cov.f1": "콘크리트",
  "cov.f1d": "무근, 철근, 프리스트레스트, 경량",
  "cov.f2": "강재 및 기타 금속",
