  "cov.f5d": "구조물 주변의 지반, 사면, 물",
  "cov.f6": "도장, 미장, 줄눈, 받침",
  "cov.f6d": "보호 및 기능 시스템",
  "cov.regions": "지식은 미국, 일본, 유럽연합, 캐나다, 영국, 뉴질랜드, 튀르키예의 지침과 연구, 그리고 국제 자료에서 나옵니다.",
  "stat.units2": "148개 출처의 지식 단위",
  "stat.rules": "콘크리트 등급 판정 규칙",
  "stat.damage": "사진에서 인식하는 손상 유형",
  "stat.crack": "처음 보는 테스트 이미지에서의 균열 검출 정밀도",
  "stat.note2": "Tecto 1단계 연구 기준, 2026년 11월. 학습에 쓰지 않은 테스트 세트에서 측정했으며, 모든 사진에 대한 보장은 아닙니다.",
  "demo.i.damp-any.int": "흰 석출물이 있는 수위선 모양 자국은 습기가 부재 안으로 스며들었다가 표면에서 마르는 경우에 해당합니다.",
  "demo.i.damp-any.short": "습기?",
  "demo.i.damp-any.causes": "지면에서 올라오는 물, 배관이나 홈통 누수, 또는 바닥보다 높은 외부 지면.",
  "demo.dm.damp-any.check": "누수, 홈통, 외부 지면 높이, 그리고 표면이 부서지거나 녹 얼룩이나 균열이 있는지.",
  "demo.dm.damp-any.change": "계속 퍼지는 습기, 또는 표면에 부서짐, 녹 얼룩, 균열이 나타나면 등급을 높입니다.",
  "demo.m.dampVisible": "습기는 보이는 가장 낮은 부분에서 약 {h} 높이까지 올라와 있습니다."
