  "proj.context-guardian.tag": "Ferramentas para programadores",
  "proj.context-guardian.tagline": "Mantém os agentes de código dentro do mapa da sua app",
  "proj.context-guardian.desc": "Antes de um agente de código editar, o Context Guardian indica-lhe as funcionalidades, regras e verificações que a tarefa envolve. No fim, compara a alteração com esse mapa e reporta o que o agente deixou escapar.",
  "proj.safe-eject.tag": "Utilitário para macOS",
  "proj.safe-eject.tagline": "Ejete com segurança os discos externos do Mac",
  "proj.safe-eject.desc": "Encontre todos os processos que mantêm ocupado o disco externo do Mac, de agentes de IA e terminais a servidores de desenvolvimento e Spotlight, veja porquê e ejete o disco em segurança.",
  "proj.polyshot.tag": "Ferramenta de design",
  "proj.polyshot.tagline": "Estúdio de capturas para as lojas",
  "proj.polyshot.desc": "O PolyShot é o estúdio da Careo para capturas da App Store e do Google Play: um só design, localizado em todos os idiomas de que precisar e dimensionado para cada dispositivo.",
