  "chip.inDev": "Em desenvolvimento",
  "proj.tsi.tag": "IA estrutural",
  "proj.tsi.short": "Nossa pesquisa em inteligência de danos estruturais: ler fotos de estruturas com contexto e conhecimento de engenharia, ligando cada conclusão às suas evidências.",
  "proj.tsi.desc": "O TSI lê fotos de danos visíveis em estruturas junto com o contexto de engenharia, o histórico de inspeções e o conhecimento técnico. Ele mostra o que vê, o que isso pode significar e o que fazer em seguida, e nunca trata uma foto isolada como prova de que uma estrutura é segura.",
  "proj.tsi.how": "Como ele raciocina",
  "proj.tsi.h1.t": "Lê a foto *no seu contexto*",
  "proj.tsi.h1.s": "Elemento, material, escala e histórico do dano",
  "proj.tsi.h2.t": "Apoiado em *normas e estudos*",
  "proj.tsi.h2.s": "Orientações dos EUA, do Japão, da Europa e não só",
  "proj.tsi.h3.t": "Um relatório *claro*, não um veredicto",
  "proj.tsi.h3.s": "O que vê, o que pode significar, o que fazer",
  "proj.tsi.h4.t": "Conclusões *baseadas em evidências*",
  "proj.tsi.h4.s": "Cada afirmação ligada à sua fonte",
  "proj.tsi.h5.t": "Medido, com *incerteza*",
  "proj.tsi.h5.s": "Escala e confiança sempre visíveis",
  "proj.tsi.h6.t": "O desconhecido continua *desconhecido*",
  "proj.tsi.h6.s": "O contexto que falta nunca é adivinhado",
  "proj.tsi.reasonTitle": "Uma leitura cuidadosa, nunca um veredito",
  "proj.tsi.reasonText": "O TSI separa três coisas em tudo o que produz, para que uma observação nunca seja confundida com uma conclusão de engenharia.",
  "proj.tsi.r1.t": "Observação",
  "proj.tsi.r1.d": "O que as evidências sustentam diretamente.",
  "proj.tsi.r1.e": "Há uma fissura diagonal visível na superfície da viga, com cerca de 1,2 mm de largura, sujeita à incerteza de escala.",
  "proj.tsi.r2.t": "Interpretação",
  "proj.tsi.r2.d": "Com o que o padrão pode ser compatível, dado o contexto.",
  "proj.tsi.r2.e": "A direção pode indicar um padrão ligado ao cisalhamento, mas uma foto sozinha não confirma a causa.",
  "proj.tsi.r3.t": "Recomendação",
  "proj.tsi.r3.d": "O que considerar fazer em seguida.",
  "proj.tsi.r3.e": "Peça a um engenheiro estrutural qualificado que inspecione a viga, principalmente se a fissura for nova ou estiver aumentando.",
  "proj.tsi.status": "Pesquisa e desenvolvimento",
  "proj.tsi.focusLabel": "Foco",
  "proj.tsi.focus": "Danos visíveis em estruturas e construções",
  "proj.tsi.contact": "Trabalha com inspeções, dados estruturais ou pesquisa? Vamos adorar falar com você.",
  "range.eyebrow": "Nosso alcance",
  "range.title": "De quebra-cabeças aconchegantes à inteligência estrutural.",
  "range.text": "O mesmo cuidado em tudo o que fazemos: jogos e apps do dia a dia hoje, e pesquisa que ajuda as pessoas a entender as estruturas ao seu redor.",
  "range.cta": "Conheça o TSI",
