  "demo.v.crack-beam-rc.seen": "Uma linha diagonal semelhante a uma fissura sobe do apoio em direção ao meio do vão, com uma ramificação curta.",
  "demo.v.spall-column-rc.seen": "O concreto se desprendeu da face do pilar, expondo duas barras de armadura corroídas e um estribo, com escorrimentos de ferrugem abaixo; uma fissura diagonal atravessa a área danificada.",
  "demo.v.damp-wall-masonry.seen": "A parte de baixo de uma parede de tijolos está mais escura e parece úmida, com depósitos brancos de sais ao longo de uma linha ondulada.",
  "demo.i.crack-beam-rc.int": "A direção perto do apoio pode indicar um padrão ligado ao cisalhamento. A foto sozinha não confirma a causa.",
  "demo.i.crack-beam-rc.short": "Pode indicar cisalhamento",
  "demo.i.crack-beam-rc.causes": "Esforço de cisalhamento perto do apoio, sobrecarga ou armadura menor que a necessária.",
  "demo.i.crack-beam-masonry.int": "Uma verga de tijolos que cedeu no meio, com uma fissura em escada subindo a partir da sua extremidade, costuma ser compatível com uma verga que está cedendo ou perdendo o apoio, por exemplo uma verga de aço corroída ou ausente por trás dos tijolos.",
  "demo.i.crack-beam-masonry.short": "Verga cedendo?",
  "demo.i.crack-beam-masonry.causes": "Uma verga de aço corroída, ausente ou subdimensionada por trás dos tijolos, apoio insuficiente nas extremidades, ou movimento da parede nos apoios.",
  "demo.i.fine-rc.short": "Retração ou reação?",
  "demo.i.fine-rc.causes": "Craquelamento por secagem precoce da superfície do concreto ou, mais raramente, reação álcali-agregado no interior do concreto.",
  "demo.i.fine-masonry.int": "Fissuras finas em forma de mapa no reboco ou no gesso costumam ser compatíveis com retração superficial, e não com movimento estrutural.",
  "demo.i.fine-masonry.short": "Retração superficial?",
  "demo.i.fine-masonry.causes": "Retração por secagem do reboco ou do gesso, ou variações de temperatura na superfície.",
  "demo.i.spall-rc.int": "Isso é compatível com a corrosão da armadura empurrando o cobrimento de concreto para fora. Quanto aço foi perdido não pode ser avaliado pela foto.",
  "demo.i.spall-rc.short": "Ligado à corrosão?",
  "demo.i.spall-rc.causes": "Água e cloretos, ou carbonatação, chegando ao aço por um cobrimento fino ou fissurado.",
