  "proj.context-guardian.tag": "Инструменты разработчика",
  "proj.context-guardian.tagline": "Держит ИИ-агентов в пределах карты вашего приложения",
  "proj.context-guardian.desc": "Перед правкой Context Guardian сообщает ИИ-агенту, какие функции, правила и проверки затрагивает задача. После работы сравнивает изменения с этой картой и сообщает, что агент упустил.",
