  "hero.ctaWork": "Смотреть портфолио",
  "hero.github": "Открытый код на GitHub",
  "chip.inDev": "В разработке",
  "proj.tsi.tag": "ИИ для конструкций",
  "proj.tsi.short": "Наше исследование в области анализа повреждений конструкций: чтение фотографий сооружений с учётом инженерного контекста и знаний, где каждый вывод опирается на доказательства.",
  "proj.tsi.desc": "TSI анализирует фотографии видимых повреждений сооружений вместе с инженерным контекстом, историей обследований и техническими знаниями. Он сообщает, что видно, что это может означать и что делать дальше, и никогда не считает одну фотографию доказательством безопасности сооружения.",
  "proj.tsi.how": "Как он рассуждает",
  "proj.tsi.h1.t": "Читает фото *в контексте*",
  "proj.tsi.h1.s": "Элемент, материал, масштаб и история повреждения",
  "proj.tsi.h2.t": "Опирается на *нормы и исследования*",
  "proj.tsi.h2.s": "Руководства США, Японии, Европы и других стран",
  "proj.tsi.h3.t": "*Понятный* отчёт, а не приговор",
  "proj.tsi.h3.s": "Что видно, что это может значить, что делать",
  "proj.tsi.h4.t": "Выводы, *основанные на доказательствах*",
  "proj.tsi.h4.s": "Каждое утверждение прослеживается до источника",
  "proj.tsi.h5.t": "Измерения с *неопределённостью*",
  "proj.tsi.h5.s": "Масштаб и уверенность всегда на виду",
  "proj.tsi.h6.t": "Неизвестное остаётся *неизвестным*",
  "proj.tsi.h6.s": "Недостающий контекст никогда не угадывается",
  "proj.tsi.reasonTitle": "Внимательный анализ, а не приговор",
  "proj.tsi.reasonText": "TSI всегда разделяет три вещи, чтобы наблюдение никогда не принималось за инженерный вывод.",
  "proj.tsi.r1.t": "Наблюдение",
  "proj.tsi.r1.d": "Что прямо подтверждают данные.",
  "proj.tsi.r1.e": "На поверхности балки видна диагональная трещина шириной около 1,2 мм с учётом погрешности масштаба.",
  "proj.tsi.r2.t": "Интерпретация",
  "proj.tsi.r2.d": "Чему может соответствовать картина с учётом контекста.",
  "proj.tsi.r2.e": "Направление может указывать на сдвиговую картину, но по одной фотографии причину подтвердить нельзя.",
  "proj.tsi.r3.t": "Рекомендация",
  "proj.tsi.r3.d": "Что стоит сделать дальше.",
  "proj.tsi.r3.e": "Пригласите квалифицированного инженера-конструктора осмотреть балку, особенно если трещина новая или растёт.",
  "proj.tsi.status": "Исследования и разработка",
  "proj.tsi.focusLabel": "Направление",
  "proj.tsi.focus": "Видимые повреждения сооружений и построек",
  "proj.tsi.contact": "Занимаетесь обследованиями, данными о конструкциях или исследованиями? Будем рады вашему письму.",
  "range.eyebrow": "Наш диапазон",
  "range.title": "От уютных головоломок до структурного интеллекта.",
  "range.text": "Одна и та же забота во всём, что мы делаем: сегодня игры и приложения на каждый день, а также исследования, которые помогают понимать окружающие сооружения.",
  "range.cta": "Знакомьтесь: TSI",
