  "proj.context-guardian.tag": "Herramientas para desarrolladores",
  "proj.context-guardian.tagline": "Mantiene a los agentes de código dentro del mapa de tu app",
  "proj.context-guardian.desc": "Antes de que un agente de código edite, Context Guardian le indica qué funciones, reglas y comprobaciones toca la tarea. Al terminar, compara el cambio con ese mapa e informa de lo que el agente pasó por alto.",
  "proj.safe-eject.tag": "Utilidad para macOS",
  "proj.safe-eject.tagline": "Expulsa con seguridad los discos externos de tu Mac",
  "proj.safe-eject.desc": "Encuentra cada proceso que mantiene ocupado el disco externo de tu Mac, desde agentes de IA y terminales hasta servidores de desarrollo y Spotlight, descubre por qué y expulsa el disco con seguridad.",
  "proj.polyshot.tag": "Herramienta de diseño",
  "proj.polyshot.tagline": "Estudio de capturas para tiendas",
  "proj.polyshot.desc": "PolyShot es el estudio de Careo para capturas de App Store y Google Play: un solo diseño, traducido a todos los idiomas que necesites y adaptado a cada dispositivo.",
