  "hero.github": "Código abierto en GitHub",
  "chip.inDev": "En desarrollo",
  "proj.tsi.tag": "IA estructural",
  "proj.tsi.short": "Nuestra investigación en inteligencia de daños estructurales: leer fotos de estructuras con contexto y conocimiento de ingeniería, vinculando cada conclusión a sus pruebas.",
  "proj.tsi.desc": "TSI lee fotos de daños visibles en estructuras junto con el contexto de ingeniería, el historial de inspecciones y el conocimiento técnico. Indica lo que ve, lo que puede significar y qué hacer a continuación, y nunca toma una foto por sí sola como prueba de que una estructura es segura.",
  "proj.tsi.how": "Cómo razona",
  "proj.tsi.h1.t": "Lee la foto *en su contexto*",
  "proj.tsi.h1.s": "Elemento, material, escala e historial del daño",
  "proj.tsi.h2.t": "Respaldado por *normas e investigación*",
  "proj.tsi.h2.s": "Guías de EE. UU., Japón, Europa y más",
  "proj.tsi.h3.t": "Un informe *claro*, no un veredicto",
  "proj.tsi.h3.s": "Qué ve, qué puede significar, qué hacer",
  "proj.tsi.h4.t": "Conclusiones *basadas en pruebas*",
  "proj.tsi.h4.s": "Cada afirmación vinculada a su fuente",
  "proj.tsi.h5.t": "Medido, con su *incertidumbre*",
  "proj.tsi.h5.s": "Escala y confianza siempre visibles",
  "proj.tsi.h6.t": "Lo desconocido sigue *desconocido*",
  "proj.tsi.h6.s": "El contexto que falta nunca se adivina",
  "proj.tsi.reasonTitle": "Una lectura cuidadosa, nunca un veredicto",
  "proj.tsi.reasonText": "TSI separa tres cosas en todo lo que produce, para que una observación nunca se confunda con una conclusión de ingeniería.",
  "proj.tsi.r1.t": "Observación",
  "proj.tsi.r1.d": "Lo que las pruebas respaldan directamente.",
  "proj.tsi.r1.e": "Se ve una grieta diagonal en la superficie de la viga, de unos 1,2 mm de ancho, sujeta a la incertidumbre de escala.",
  "proj.tsi.r2.t": "Interpretación",
  "proj.tsi.r2.d": "Con qué puede encajar el patrón, según el contexto.",
  "proj.tsi.r2.e": "Su dirección puede encajar con un patrón de cortante, pero una foto por sí sola no confirma la causa.",
  "proj.tsi.r3.t": "Recomendación",
  "proj.tsi.r3.d": "Qué conviene hacer a continuación.",
  "proj.tsi.r3.e": "Pide a un ingeniero estructural cualificado que inspeccione la viga, sobre todo si la grieta es nueva o está creciendo.",
  "proj.tsi.status": "Investigación y desarrollo",
  "proj.tsi.focusLabel": "Enfoque",
  "proj.tsi.focus": "Daños visibles en estructuras y construcciones",
  "proj.tsi.contact": "¿Trabajas en inspecciones, datos estructurales o investigación? Nos encantaría saber de ti.",
  "range.eyebrow": "Nuestro abanico",
  "range.title": "De rompecabezas acogedores a la inteligencia estructural.",
  "range.text": "El mismo cuidado en todo lo que hacemos: juegos y apps del día a día hoy, e investigación que ayuda a entender las estructuras que nos rodean.",
  "range.cta": "Conoce TSI",
