  "demo.v.crack-beam-rc.seen": "Una línea diagonal similar a una grieta sube desde el apoyo hacia el centro del vano, con una ramificación corta.",
  "demo.v.spall-column-rc.seen": "El hormigón se ha desprendido de la cara del pilar y deja a la vista dos barras de armadura corroídas y un estribo, con chorreones de óxido debajo; una grieta diagonal atraviesa la zona dañada.",
  "demo.v.damp-wall-masonry.seen": "La parte baja de un muro de ladrillo está más oscura y parece húmeda, con depósitos blancos de sales a lo largo de una línea ondulada.",
  "demo.i.crack-beam-rc.int": "Su dirección cerca del apoyo puede encajar con un patrón de cortante. La foto por sí sola no confirma la causa.",
  "demo.i.crack-beam-rc.short": "Puede ser cortante",
  "demo.i.crack-beam-rc.causes": "Esfuerzo cortante cerca del apoyo, sobrecarga o menos armadura de la necesaria.",
  "demo.i.crack-beam-masonry.int": "Un dintel de ladrillo que ha bajado en el centro, con una grieta escalonada que sube desde su extremo, suele encajar con un dintel que cede o está perdiendo su apoyo, por ejemplo un dintel de acero corroído o inexistente detrás de los ladrillos.",
  "demo.i.crack-beam-masonry.short": "¿Dintel cediendo?",
  "demo.i.crack-beam-masonry.causes": "Un dintel de acero corroído, inexistente o infradimensionado detrás de los ladrillos, apoyo insuficiente en sus extremos, o movimiento del muro en los apoyos.",
  "demo.i.fine-rc.short": "¿Retracción o reacción?",
  "demo.i.fine-rc.causes": "Cuarteo por secado temprano de la superficie del hormigón o, con menos frecuencia, reacción álcali-sílice en el interior del hormigón.",
  "demo.i.fine-masonry.int": "Las grietas finas en forma de mapa en un revoco o enlucido suelen encajar con una retracción superficial más que con un movimiento estructural.",
  "demo.i.fine-masonry.short": "¿Retracción superficial?",
  "demo.i.fine-masonry.causes": "Retracción por secado del revoco o del enlucido, o cambios de temperatura en la superficie.",
  "demo.i.spall-rc.int": "Esto encaja con la corrosión de la armadura, que empuja el recubrimiento de hormigón hacia fuera. Cuánto acero se ha perdido no se puede juzgar por la foto.",
  "demo.i.spall-rc.short": "¿Por corrosión?",
  "demo.i.spall-rc.causes": "Agua y cloruros, o carbonatación, que llegan al acero a través de un recubrimiento delgado o fisurado.",
  "demo.i.damp-masonry.int": "Una línea de humedad con sales encaja con humedad que sube por la mampostería o la atraviesa y se seca en la superficie.",
  "demo.i.damp-masonry.short": "¿Humedad ascendente?",
  "demo.i.damp-masonry.causes": "Humedad por capilaridad, una barrera antihumedad dañada, fugas en tuberías o canalones, o terreno exterior más alto que el suelo.",
  "demo.dm.crack.dont": "No rellenes ni pintes la grieta antes de que la inspeccionen.",
  "demo.dm.crack.change": "Una grieta nueva o que crece sube el nivel; una grieta antigua que no ha cambiado en años reduce la preocupación.",
  "demo.dm.fine.do": "Registra la zona con una referencia de escala, para que fotos posteriores muestren si cambia.",
  "demo.dm.fine.change": "Grietas más anchas, rectas o escalonadas, o grietas que crecen, subirían el nivel.",
  "demo.dm.spall-rc.dont": "No lo parchees con mortero ni pintes el acero antes de evaluar la causa y la pérdida de acero.",
  "demo.dm.damp-masonry.check": "Fugas, canalones y el nivel del terreno exterior, y si los ladrillos o el mortero se desmoronan.",
  "demo.dm.damp-masonry.change": "Ladrillos o mortero que se desmoronan, o humedad que sigue extendiéndose, subirían el nivel.",
