  "cov.f6d": "Sistemas de protección y funcionales",
  "cov.regions": "El conocimiento procede de guías e investigación de Estados Unidos, Japón, la Unión Europea, Canadá, el Reino Unido, Nueva Zelanda y Turquía, además de fuentes internacionales.",
  "stat.units2": "unidades de conocimiento de 148 fuentes",
