  "demo.i.damp-any.int": "Una línea de humedad con depósitos blancos encaja con humedad que entra en el elemento y se seca en la superficie.",
  "demo.i.damp-any.short": "¿Humedad?",
  "demo.i.damp-any.causes": "Agua del terreno, una tubería o un canalón con fugas, o terreno exterior más alto que el suelo.",
