  "proj.tsi.tag": "Yapısal yapay zekâ",
  "proj.tsi.short": "Yapısal hasar zekâsı üzerine araştırmamız: yapıların fotoğraflarını mühendislik bağlamı ve bilgisiyle birlikte okumak ve her sonucu kanıtına bağlı tutmak.",
  "proj.tsi.desc": "TSI, yapılardaki görünür hasarın fotoğraflarını mühendislik bağlamı, muayene geçmişi ve teknik bilgiyle birlikte okur. Ne gördüğünü, bunun ne anlama gelebileceğini ve sonra ne yapılması gerektiğini söyler; tek bir fotoğrafı asla bir yapının güvenli olduğunun kanıtı saymaz.",
  "proj.tsi.how": "Nasıl düşünür",
  "proj.tsi.h1.t": "Fotoğrafı *bağlamıyla* okur",
  "proj.tsi.h1.s": "Eleman, malzeme, ölçek ve hasar geçmişi",
  "proj.tsi.h2.t": "*Standartlara ve araştırmalara* dayanır",
  "proj.tsi.h2.s": "ABD, Japonya, Avrupa ve ötesinden kılavuzlar",
  "proj.tsi.h3.t": "Hüküm değil, *anlaşılır* bir rapor",
  "proj.tsi.h3.s": "Ne gördüğü, ne anlama gelebileceği, ne yapılacağı",
  "proj.tsi.h4.t": "*Kanıta dayalı* sonuçlar",
  "proj.tsi.h4.s": "Her iddia kaynağına kadar izlenebilir",
  "proj.tsi.h5.t": "Ölçer, *belirsizliğini* de gösterir",
  "proj.tsi.h5.s": "Ölçek ve güven düzeyi her zaman görünür",
  "proj.tsi.h6.t": "Bilinmeyen *bilinmeyen* kalır",
  "proj.tsi.h6.s": "Eksik bağlam asla tahminle doldurulmaz",
  "proj.tsi.reasonTitle": "Dikkatli bir okuma, asla bir hüküm değil",
  "proj.tsi.reasonText": "TSI ürettiği her şeyde üç şeyi birbirinden ayırır; böylece bir gözlem asla mühendislik sonucu sanılmaz.",
  "proj.tsi.r1.t": "Gözlem",
  "proj.tsi.r1.d": "Kanıtın doğrudan desteklediği şey.",
