  "demo.v.crack-column-masonry.seen": "Tuğla ayağın ortasında neredeyse düşey iki uzun çatlak tuğlaların ve derzlerin içinden geçiyor; bazı tuğlalar yarılmış.",
  "demo.v.crack-wall-rc.seen": "Pencerenin sağ alt köşesinden başlayan ince, çapraz bir çatlak beton duvar boyunca aşağı iniyor.",
  "demo.v.crack-wall-masonry.seen": "Pencere denizliğinin köşesinden başlayan kademeli bir çatlak harç derzleri boyunca zikzak çizerek ilerliyor; birkaç tuğlayı da yarmış.",
  "demo.v.fine-beam-rc.seen": "Kirişin yan yüzünün ortasını ince, harita gibi çatlaklardan oluşan bir ağ kaplıyor.",
  "demo.v.fine-column-rc.seen": "Kolon yüzeyinin ortasını ince, harita gibi çatlaklardan oluşan bir ağ kaplıyor.",
  "demo.v.fine-column-masonry.seen": "Ayağın sıvasını ince, harita gibi çatlaklar kaplıyor; alt köşelerden birinin yakınında sıva dökülmüş ve tuğla görünüyor.",
  "demo.v.fine-wall-rc.seen": "Beton duvarın ortasını ince, harita gibi çatlaklardan oluşan bir ağ kaplıyor.",
  "demo.v.fine-wall-masonry.seen": "Duvarın sıvasını ince, harita gibi çatlaklar kaplıyor; alt köşelerden birinin yakınında sıva dökülmüş ve tuğla görünüyor.",
  "demo.v.spall-beam-rc.seen": "Kolonun yanında, kirişin alt kenarı boyunca beton kopmuş; korozyona uğramış bir donatı çubuğu ve iki etriye açığa çıkmış, altında pas izleri var.",
  "demo.v.spall-column-masonry.seen": "Tuğla ayağın tabanına yakın birkaç tuğlanın yüzü pul pul kalkıp ufalanmış; geride pürüzlü, daha açık renkli tuğla ve biraz toz kalmış.",
  "demo.v.spall-wall-rc.seen": "Duvardan beton kopmuş; korozyona uğramış çelik hasır açığa çıkmış ve aşağı doğru pas izleri akmış.",
  "demo.v.spall-wall-masonry.seen": "Duvarın ortasındaki birkaç tuğlanın yüzü pul pul kalkıp ufalanmış, geride pürüzlü ve daha açık renkli tuğla kalmış; harç da hafifçe aşınmış.",
  "demo.v.damp-column-rc.seen": "Beton kolonun alt kısmı daha koyu ve nemli görünüyor; dalgalı bir çizgi boyunca beyaz birikintiler, bir köşesinde de küçük bir pas lekesi var.",
  "demo.v.damp-column-masonry.seen": "Tuğla ayağın alt kısmı daha koyu ve nemli görünüyor; dalgalı bir çizgi boyunca beyaz tuz birikintileri var.",
  "demo.v.damp-wall-rc.seen": "Beton duvarın alt kısmı daha koyu ve nemli görünüyor; dalgalı bir çizgi boyunca beyaz birikintiler ve hafif bir pas lekesi var.",
  "demo.i.crack-column-rc.int": "Kolonu kesen çapraz bir çatlak kesmeyle ilişkili bir desene uyabilir; bu, kolonda kirişte olduğundan daha önemlidir. Tek bir fotoğraf nedeni doğrulayamaz.",
  "demo.i.crack-column-rc.short": "Kesmeye uyabilir",
  "demo.i.crack-column-rc.causes": "Deprem gibi yatay yüklerden kaynaklanan kesme, yetersiz ya da çok seyrek etriye veya aşırı yükleme.",
  "demo.i.crack-column-masonry.int": "Bir ayakta tuğlaları yaran, neredeyse düşey çatlaklar genellikle ayağa üstten fazla yük binmesine uyar. Tek bir fotoğraf nedeni doğrulayamaz.",
  "demo.i.crack-column-masonry.short": "Aşırı yük?",
  "demo.i.crack-column-masonry.causes": "Ayağın tasarlandığından fazla yük, zayıf tuğla ya da harç veya kenarına çok yakın oturan bir yük.",
  "demo.i.crack-wall-rc.int": "Pencere köşesinden çıkan ince bir çatlak genellikle rötre ya da hareket nedeniyle köşede toplanan gerilmeye uyar. Duvarda bu, kiriş ya da kolondakine göre genellikle daha az endişe vericidir.",
  "demo.i.crack-wall-rc.short": "Köşe gerilmesi?",
  "demo.i.crack-wall-rc.causes": "Boşluk çevresinde serbestçe büzülemeyen betonun rötresi, sıcaklık hareketleri ya da köşede yetersiz donatı.",
  "demo.i.crack-wall-masonry.int": "Pencere köşesinden başlayıp harç derzlerini izleyen kademeli bir çatlak genellikle alttaki temelin farklı oturmasına uyar.",
  "demo.i.crack-wall-masonry.short": "Oturma?",
  "demo.i.crack-wall-masonry.causes": "Temelde farklı oturma ya da hareket; örneğin büzülen killi zemin, sızdıran atık su boruları veya yakındaki ağaç kökleri nedeniyle.",
  "demo.i.fine-rc.int": "Beton yüzeyde ince, harita gibi çatlaklar genellikle yüzeyin erken rötresine uyar; daha seyrek olarak test gerektiren bir iç reaksiyona.",
  "demo.i.spall-masonry.int": "Tuğla yüzlerinin bu şekilde pul pul dökülmesi genellikle kendi başına yapısal bir sorundan çok, ıslak yığmada don ya da tuz hasarına uyar.",
  "demo.i.spall-masonry.short": "Don ya da tuz?",
  "demo.i.spall-masonry.causes": "Tuğladaki suyun donması, duvar kururken tuzların kristalleşmesi ya da sert çimento harcının veya su geçirmeyen kaplamaların nemi hapsetmesi.",
  "demo.i.damp-rc.int": "Beyaz birikintili bir nem çizgisi, suyun betona girip yüzeyde kurumasına uyar. Pas lekesi, yüzeye yakın çeliğin korozyona başladığını gösterebilir ya da metal bir bağlantı elemanından kaynaklanıyor olabilir; bunun yerinde kontrol edilmesi gerekir.",
  "demo.i.damp-rc.short": "Su girişi?",
  "demo.i.damp-rc.causes": "Zeminden gelen su, sızdıran bir boru ya da oluk veya dışarıdaki zeminin döşemeden yüksek olması.",
  "demo.dm.crack.do": "Çatlağın iki ucunu işaretleyip tarih atın ve ölçekle fotoğraflayın; böylece büyürse fark edilir. Ne olduğunu bir yapı mühendisine doğrulatın.",
  "demo.dm.crack-rc.check": "Yakındaki başka çatlaklar, sehim, eğiklik ya da şişkinlik olup olmadığı ve aynı çatlağın diğer yüzde de bulunup bulunmadığı.",
  "demo.dm.crack-masonry.check": "İç yüzdeki çatlaklar; şişkinlik, eğiklik ya da sehim olup olmadığı; elemana üstten ne yük bindiği; yakındaki kapı ya da pencerelerin sıkışıp sıkışmadığı ve temel yakınında sızdıran atık su boruları.",
  "demo.dm.fine.dont": "Çatlaklar genişler ya da bir hat izlemeye başlarsa arkadaki elemanın sağlam olduğunu varsaymayın.",
  "demo.dm.fine.check": "Daha geniş, düz ya da kademeli bir çatlak olup olmadığı ve yüzeye vurulduğunda boş ses gelip gelmediği.",
  "demo.dm.spall-rc.do": "Kısa sürede yetkin bir yapı mühendisine inceletin. Düşebilecek parçalara karşı çevresini boş tutun.",
  "demo.dm.spall-rc.check": "Yakında başka dökülme ya da pas lekesi ve donatı boyunca uzanan çatlaklar.",
  "demo.dm.spall-rc.change": "Kesitinin büyük kısmını kaybetmiş çelik ya da birkaç yerde benzer hasar endişeyi daha da artırır.",
  "demo.dm.spall-masonry.do": "Islanmanın kaynağını bulup durdurun, ardından hasarlı tuğlaları değerlendirtip gereken yerlerde değiştirtin.",
  "demo.dm.spall-masonry.dont": "Derzleri sert çimento harcıyla yenilemeyin ya da tuğlaları yalıtıcı bir kaplamayla kapatmayın; bu nemi hapsedip hasarı artırabilir.",
  "demo.dm.spall-masonry.check": "Sızdıran oluk ya da borular, sıçrayan yağmur suyu ya da zeminden yükselen nem, hasarın yayılıp yayılmadığı ve kaybın tuğlanın ne kadar derinine indiği.",
  "demo.dm.spall-masonry.change": "Tuğla örgüyü zayıflatacak derinlikte kayıp ya da birçok tuğlaya yayılan hasar dereceyi yükseltir.",
  "demo.dm.damp.do": "Önce su kaynağını bulup giderin, onarımdan önce kurumasını bekleyin.",
  "demo.dm.damp.dont": "Su geçirmeyen boya ya da sıvayla kapatmayın; nemi içeride hapsedebilir.",
  "demo.dm.damp-rc.check": "Sızıntılar, oluklar ve dışarıdaki zemin seviyesi; çelik boyunca pas lekesi ya da çatlak olup olmadığı.",
  "demo.dm.damp-rc.change": "Yayılan pas lekeleri, donatı boyunca çatlaklar ya da kopan beton çeliğin korozyona uğradığını gösterir ve dereceyi yükseltir.",
  "demo.call.recSoon": "Kısa sürede mühendis",
